const Bun = require('bun');
const { spawnSync } = Bun;

const args = process.argv.slice(2);
let isValid = true;

for (const arg of args) {
    const num = parseInt(arg);
    if (isNaN(num)) {
        isValid = false;
        break;
    }
}

if (!isValid) {
    process.exit(1);
}

const numbers = args.filter(arg => {
    const num = parseInt(arg);
    return !isNaN(num);
});

if (numbers.length === 0) {
    console.log(0);
    process.exit(0);
} else {
    console.log(numbers.reduce((acc, num) => acc + num, 0));
    process.exit(0);
}

